Write-Host 'Updating README and .gitignore...' -ForegroundColor Cyan

[System.IO.File]::WriteAllBytes('README.md', [System.Convert]::FromBase64String(''))
[System.IO.File]::WriteAllBytes('.gitignore', [System.Convert]::FromBase64String(''))

Write-Host 'Done! Now run:' -ForegroundColor Green
Write-Host '  git add .' -ForegroundColor Yellow
Write-Host '  git commit -m "Update README and gitignore"' -ForegroundColor Yellow
Write-Host '  git push' -ForegroundColor Yellow